from quorem_types import ListNode

class Solution:
    def segmentSums(self, head):
        dummy = ListNode(0)
        tail = dummy
        total, active = 0, False
        while head is not None:
            if head.val == 0:
                if active:
                    tail.next = ListNode(total)
                    tail = tail.next
                total, active = 0, False
            else:
                total += head.val
                active = True
            head = head.next
        if active:
            tail.next = ListNode(total)
        return dummy.next
